INSERT INTO `wp_posts` VALUES
(26381,1,'2026-06-10 11:14:28','2026-06-10 09:14:28','<!-- wp:group {\"className\":\"iss-ausstellung-care-quote\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-quote\"><!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>„Jetzt geht es uns gut.“</p>\n<!-- /wp:paragraph --><cite>Bildunterschrift zur Kinderkrippe des HF, Betriebszeitung <em>HF-Sender</em>, Nr. 16, 28. Mai 1954.</cite></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-question\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-question\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Leitfrage</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Wer betreut die Kinder, wenn die Mütter im Werk arbeiten?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Quellen erzählen von Fürsorge und Entlastung. Gleichzeitig zeigen sie, dass Kinderbetreuung auch eine Bedingung der Produktion war: Frauen sollten arbeiten können, Schichten sollten laufen, eingearbeitete Kräfte sollten im Betrieb bleiben.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-stationu002du002dsplit\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--split\"><!-- wp:image {\"id\":13824,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2023/12/HF-Sender-16-Titelseite.jpg\" alt=\"\" class=\"wp-image-13824\" /><figcaption class=\"wp-element-caption\">HF-Sender Nr. 16, Titelseite zur Kinderkrippe, 1954.</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__copy\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__copy\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">1 · Kinderkrippe</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Betreuung als Produktionsfrage</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die frühe Berichterstattung zeigt die Kinderkrippe als liebevollen Ort. Doch der Text sagt auch offen, weshalb der Betrieb sie brauchte: Die Mütter sollten sich „voll und ganz“ für die Erfüllung der Produktionspläne einsetzen können.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><strong>Quellenauszug:</strong> „Die Muttis wissen, wieviel liebevolle Geduld und rastlose Arbeit die Pflege eines Kleinkindes erfordert …“ — <em>HF-Sender</em>, 1954.</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-object-grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-object-grid\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Objektfokus</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Drei Quellen, drei Blickrichtungen</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Ausstellung bindet Archivobjekte direkt ein. Nicht als Kartengitter am Ende, sondern als kleine Beweisstücke mitten in der Erzählung.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss-wf-import/archive-object {\"setId\":13,\"memberPosition\":0,\"variant\":\"featured\"} /-->\n\n<!-- wp:iss-wf-import/archive-object {\"setId\":13,\"memberPosition\":5,\"variant\":\"featured\"} /-->\n\n<!-- wp:iss-wf-import/archive-object {\"setId\":13,\"memberPosition\":7,\"variant\":\"featured\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-stationu002du002dfull iss-ausstellung-stationu002du002ddark\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--full iss-ausstellung-station--dark\"><!-- wp:image {\"id\":23627,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/kinderheim-julius-rosenberg-gartenfront-foto-1962-65505.jpg\" alt=\"\" class=\"wp-image-23627\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__caption\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">2 · Kinderwochenheim</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Montagmorgen gebracht. Freitagnachmittag abgeholt.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Das Kinderheim „Agnes Smedley“ war zeitweise ein Kinderwochenheim. Neben Tagesgruppen gab es Heimgruppen, in denen Kinder die Woche über blieben. Für heutige Besucher ist das erklärungsbedürftig — und genau deshalb ausstellungsstark.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-album\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-album\"><!-- wp:group {\"className\":\"iss-ausstellung-care-album__grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-album__grid\"><!-- wp:group {\"className\":\"iss-ausstellung-care-album__note\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-album__note\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Dokumentarische Strecke</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Schlafen. Spielen. Hausaufgaben.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Eine Ausstellung muss hier nicht alles erklären. Drei bis vier Bilder können zeigen, dass Betreuung aus Routinen bestand: Essen, Schlafen, Lernen, Abholen, Wäsche, Wochenrhythmus.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":20899,\"sizeSlug\":\"large\",\"className\":\"iss-ausstellung-care-album__photo\"} -->\n<figure class=\"wp-block-image size-large iss-ausstellung-care-album__photo\"><img src=\"/wp-content/uploads/2026/05/TFA-6221489-1.jpg\" alt=\"\" class=\"wp-image-20899\" /><figcaption class=\"wp-element-caption\">Schlafräume im Kinderheim.</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":20100,\"sizeSlug\":\"large\",\"className\":\"iss-ausstellung-care-album__photo\"} -->\n<figure class=\"wp-block-image size-large iss-ausstellung-care-album__photo\"><img src=\"/wp-content/uploads/2026/05/drei-kinder-und-erzieherin-im-kinderheim-foto-juli-1954-64518-1.jpg\" alt=\"\" class=\"wp-image-20100\" /><figcaption class=\"wp-element-caption\">Gruppenalltag im Kinderheim.</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":13812,\"sizeSlug\":\"large\",\"className\":\"iss-ausstellung-care-album__photo\"} -->\n<figure class=\"wp-block-image size-large iss-ausstellung-care-album__photo\"><img src=\"/wp-content/uploads/2024/01/kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017.jpg\" alt=\"\" class=\"wp-image-13812\" /><figcaption class=\"wp-element-caption\">Kinder im Planschbecken, Foto 1977.</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":20102,\"sizeSlug\":\"large\",\"className\":\"iss-ausstellung-care-album__photo\"} -->\n<figure class=\"wp-block-image size-large iss-ausstellung-care-album__photo\"><img src=\"/wp-content/uploads/2026/05/TFA-549681-1.jpg\" alt=\"\" class=\"wp-image-20102\" /><figcaption class=\"wp-element-caption\">Szene im Kindergarten des Werkes, 1954.</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-stationu002du002dsplit iss-ausstellung-stationu002du002dreverse\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--split iss-ausstellung-station--reverse\"><!-- wp:image {\"id\":13809,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2024/01/kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin.jpg\" alt=\"\" class=\"wp-image-13809\" /><figcaption class=\"wp-element-caption\">Kinder mit Erzieherin am Sandkasten vor dem WF-Gebäude.</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__copy\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__copy\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">3 · Neue Mühle</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Ein Ort außerhalb der Werkhalle</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Mit „Neue Mühle“ verschiebt sich die Geschichte. Es geht nicht mehr nur um Betreuung während der Arbeitszeit, sondern um eine eigene Kinderwelt: Haus, Gelände, Erholung, Ferien und Ausflüge.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><strong>Ausstellungsentscheidung:</strong> Dieses Kapitel sollte eher bildhaft als argumentativ sein. Ein großes Foto, kurze Sätze, wenige Daten.</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-stat\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-stat\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">4 · Maßstab</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-stat__grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-stat__grid\"><!-- wp:html -->\n<div class=\"iss-ausstellung-care-stat__item\"><strong>8.615</strong><span>Beschäftigte im WF im Jahr 1990</span></div>\n<div class=\"iss-ausstellung-care-stat__item\"><strong>3.503</strong><span>davon Frauen</span></div>\n<div class=\"iss-ausstellung-care-stat__item\"><strong>1.754</strong><span>Frauen mit Kindern</span></div>\n<!-- /wp:html --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Die Zahlen holen die Ausstellung zurück in den Betrieb. Kinderbetreuung war kein Randthema. Sie betraf den Alltag vieler Familien und die Arbeitsfähigkeit eines großen Industriebetriebs.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-care-essay\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-care-essay\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">5 · Für wen?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Wochenheime waren nicht für alle gleich.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Quellen mahnen zur Vorsicht vor schnellen Urteilen. Wochenkrippen und Kinderwochenheime wirkten damals nicht nur als staatliche Zumutung, sondern auch als Lösung für Alleinerziehende, Studierende, Schichtarbeitende und Familien ohne andere Betreuung.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Gerade deshalb sollte die Ausstellung die Spannung halten: Entlastung und Zumutung, Fürsorge und Produktionsinteresse, Schutzraum und Trennung.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"iss-ausstellung-small-source\"} -->\n<p class=\"iss-ausstellung-small-source\">Quellenhintergrund: Folge 8 der Serie behandelt die Frage, für wen Wochenkrippen und Kinderwochenheime gedacht waren.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-stationu002du002dfull iss-ausstellung-stationu002du002ddark\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--full iss-ausstellung-station--dark\"><!-- wp:image {\"id\":20899,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/TFA-6221489-1.jpg\" alt=\"\" class=\"wp-image-20899\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__caption\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">6 · Ambivalenz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fürsorge genügt nicht, wenn Bindung fehlt.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Spätere Untersuchungen diskutierten mögliche Folgen von Wochenkrippen und Wochenheimen. Die Ausstellung muss diesen Teil nicht dramatisieren, aber sie sollte ihn nicht aussparen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-conclusion\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-conclusion\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kickeru002du002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Schluss</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Die Kinderbetreuung im WF war mehr als Sozialleistung.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Sie führte vom Werkstor in Krippenräume, Wochenheime und Ferienorte. Sie half Müttern, im Betrieb zu bleiben. Sie griff tief in den Familienalltag ein. Die Quellen zeigen eine Geschichte von Fürsorge, Arbeit, Organisation und Widerspruch.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"overlayMenu\":\"never\",\"className\":\"iss-ausstellung-research\",\"layout\":{\"type\":\"flex\",\"orientation\":\"horizontal\"}} -->\n<!-- wp:navigation-link {\"label\":\"Archivbestand\",\"url\":\"/archiv/?s=Kinder\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Kinder im WF\",\"url\":\"/ausstellungen/kinder-im-wf/\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Weitere Ausstellungen\",\"url\":\"/ausstellungen/\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation --></div>\n<!-- /wp:group -->','Kinder im Werk','Kinderkrippe, Wochenheim, Ferienlager und Familienalltag: Quellen zur Frage, wie das Werk für Fernmeldewesen Arbeit und Betreuung miteinander verband.','publish','closed','closed','','kinder-im-werk','','','2026-06-10 21:07:07','2026-06-10 19:07:07','',0,'http://192.168.2.31:8082/?post_type=ausstellung&#038;p=26381',0,'ausstellung','',0);
